import { promises as fs } from "node:fs";
import path from "node:path";

// Books channel data, generated by scripts/books-sync.py from flexappdev/bookai.

export type OurBook = {
  slug: string;
  title: string;
  subtitle?: string | null;
  volume?: string | null;
  blurb?: string | null;
  collection?: string | null;
  chapters: number;
  free: number;
  cover?: string | null;
  url: string;
  buy?: string | null;
  price?: number | null;
  hasFeed: boolean;
};

export type BookChapter = {
  n: number;
  part?: string | null;
  title: string;
  tease: string;
  facts: { label: string; value: string }[];
  image?: string | null;
  video?: string | null;
  poster?: string | null;
  read?: string | null;
  free: boolean;
  minutes?: number | null;
};

export type BooksChannel = {
  generatedAt: string;
  bookai: string | null;
  counts: { ours: number; ourChapters: number; topNonfiction: number; topNonfictionTarget: number };
  ours: OurBook[];
};

export type RankedBook = {
  rank: number;
  title: string;
  author: string;
  year: number | null;
  pages: number | null;
  rating: number | null;
  ratings: number;
  shelves: string[];
  gr: string;
};

type TopNonfictionFile = {
  columns: string[];
  target: number;
  minRatings: number;
  rankedBy: string;
  sources: { name: string; licence: string; url: string }[];
  rows: unknown[][];
};

export const TOP_PAGE_SIZE = 100;
const ROOT = path.join(process.cwd(), "data", "books");
const SLUG = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;

async function readJson<T>(file: string): Promise<T | null> {
  try {
    return JSON.parse(await fs.readFile(file, "utf8")) as T;
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return null;
    throw error;
  }
}

export async function getBooksChannel(): Promise<BooksChannel> {
  const channel = await readJson<BooksChannel>(path.join(ROOT, "channel.json"));
  if (!channel) {
    return {
      generatedAt: "",
      bookai: null,
      counts: { ours: 0, ourChapters: 0, topNonfiction: 0, topNonfictionTarget: 10_000 },
      ours: [],
    };
  }
  return channel;
}

export async function getOurBook(slug: string) {
  if (!SLUG.test(slug)) return null;
  const channel = await getBooksChannel();
  const book = channel.ours.find((b) => b.slug === slug);
  if (!book) return null;
  const feed = await readJson<{ chapters: BookChapter[] }>(path.join(ROOT, "bookai", `${slug}.json`));
  return { book, chapters: feed?.chapters ?? [] };
}

let topCache: Promise<TopNonfictionFile | null> | null = null;
function loadTop() {
  topCache ??= readJson<TopNonfictionFile>(path.join(ROOT, "top-nonfiction.json"));
  return topCache;
}

export async function getTopNonfiction(page: number) {
  const file = await loadTop();
  if (!file) return null;
  const total = file.rows.length;
  const pages = Math.max(1, Math.ceil(total / TOP_PAGE_SIZE));
  if (!Number.isInteger(page) || page < 1 || page > pages) return null;
  const start = (page - 1) * TOP_PAGE_SIZE;
  const col = (name: string) => file.columns.indexOf(name);
  const books: RankedBook[] = file.rows.slice(start, start + TOP_PAGE_SIZE).map((row, i) => ({
    rank: start + i + 1,
    title: row[col("title")] as string,
    author: row[col("author")] as string,
    year: row[col("year")] as number | null,
    pages: row[col("pages")] as number | null,
    rating: row[col("rating")] as number | null,
    ratings: row[col("ratings")] as number,
    shelves: (row[col("shelves")] as string[]) ?? [],
    gr: row[col("gr")] as string,
  }));
  return {
    books,
    page,
    pages,
    total,
    target: file.target,
    minRatings: file.minRatings,
    rankedBy: file.rankedBy,
    sources: file.sources,
  };
}

export function goodreadsUrl(id: string) {
  return `https://www.goodreads.com/book/show/${encodeURIComponent(id)}`;
}

export function compactCount(n: number) {
  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(1).replace(/\.0$/, "")}M`;
  if (n >= 1_000) return `${Math.round(n / 1_000)}K`;
  return String(n);
}
